package tokenizer

import java.time.{LocalDate, LocalDateTime}
import scala.collection.immutable.Map

/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This Scala implementation demonstrates:
 * - Algebraic data types with sealed traits and case classes
 * - Proper use of Option and Either for error handling
 * - Type classes for polymorphism
 * - Immutable data structures
 * - Functional programming patterns
 */
object TokenizerModule {

  // ============================================================================
  // Type Definitions
  // ============================================================================

  /**
   * Enumeration of token types.
   */
  sealed trait TokenType extends Product with Serializable

  object TokenType {
    case object String extends TokenType
    case object Numeric extends TokenType
    case object Temporal extends TokenType
    case object Structured extends TokenType
    case object Binary extends TokenType
    case object Null extends TokenType

    def fromString(value: String): Option[TokenType] = value.toLowerCase match {
      case "string" => Some(String)
      case "numeric" => Some(Numeric)
      case "temporal" => Some(Temporal)
      case "structured" => Some(Structured)
      case "binary" => Some(Binary)
      case "null" => Some(Null)
      case _ => None
    }
  }

  /**
   * Represents a token with its value, type, and optional metadata.
   * Immutable case class for thread-safety and predictability.
   */
  final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
  ) {
    /**
     * Return a new token with additional metadata merged in.
     */
    def withMetadata(additionalMetadata: (String, Any)*): Token =
      copy(metadata = metadata ++ additionalMetadata.toMap)

    def withMetadata(newMetadata: Map[String, Any]): Token =
      copy(metadata = metadata ++ newMetadata)
  }

  /**
   * Type class for types that can be converted to tokens.
   */
  trait ToToken[A] {
    def toToken(value: A): Token
  }

  /**
   * Type class for normalization of token values.
   */
  trait TokenNormalizer {
    def normalize(value: String): String
  }

  // ============================================================================
  // Tokenizer Base Abstraction
  // ============================================================================

  /**
   * Base trait for all tokenizers.
   * Supports single value tokenization and batch processing via views.
   */
  trait BaseTokenizer[A] {
    def tokenize(value: A): Token

    def tokenizeBatch(values: Iterable[A]): IterableOnce[Token] =
      new IterableOnce[ViewToken](values.iterator.map(tokenize))

    protected class ViewToken(t: Token) extends IterableOnce[Token] {
      def iterator: Iterator[Token] = Iterator(t)
    }
  }

  // ============================================================================
  // Specific Tokenizer Implementations
  // ============================================================================

  /**
   * Tokenizer for string and byte types.
   * Supports configurable encoding and normalization.
   */
  final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: Option[TokenNormalizer] = None
  ) extends BaseTokenizer[String] {

    override def tokenize(value: String): Token = {
      val normalized = normalizer.fold(value)(_.normalize(value))
      Token(normalized, TokenType.String)
    }

    /**
     * Tokenize bytes by first decoding to string.
     */
    def tokenizeBytes(bytes: Array[Byte]): Token = {
      val str = new String(bytes, encoding)
      tokenize(str)
    }
  }

  /**
   * Tokenizer for numeric types.
   * Supports configurable precision for floating point values.
   */
  final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
  ) extends BaseTokenizer[Number] {

    override def tokenize(value: Number): Token = {
      val strValue = value match {
        case d: java.math.BigDecimal =>
          s"%.${precision}f".format(d.doubleValue)
        case d: java.math.BigInteger =>
          d.toString
        case d: Double =>
          s"%.${precision}f".format(d)
        case f: Float =>
          s"%.${precision}f".format(f.toDouble)
        case l: Long =>
          l.toString
        case i: Integer =>
          i.toString
        case _ =>
          value.toString
      }

      Token(strValue, TokenType.Numeric, Map("originalType" -> value.getClass.getSimpleName))
    }
  }

  /**
   * Tokenizer for date/time types.
   * Supports custom format strings and ISO defaults.
   */
  final class TemporalTokenizer(
    formatStr: Option[String] = None
  ) extends BaseTokenizer[LocalDateTime] {

    private val isoFormat = "yyyy-MM-dd'T'HH:mm:ss"
    private val dateFormat = "yyyy-MM-dd"

    override def tokenize(value: LocalDateTime): Token = {
      val fmt = formatStr.getOrElse(isoFormat)
      Token(value.format(java.time.format.DateTimeFormatter.ofPattern(fmt)), TokenType.Temporal)
    }

    /**
     * Tokenize a LocalDate with date-only format.
     */
    def tokenizeDate(value: LocalDate): Token = {
      val fmt = formatStr.getOrElse(dateFormat)
      Token(value.format(java.time.format.DateTimeFormatter.ofPattern(fmt)), TokenType.Temporal)
    }
  }

  // ============================================================================
  // Universal Tokenizer
  // ============================================================================

  /**
   * Universal tokenizer that dispatches to appropriate tokenizer based on type.
   * Demonstrates pattern matching on types.
   */
  class UniversalTokenizer(
    stringTokenizer: StringTokenizer = new StringTokenizer(),
    numericTokenizer: NumericTokenizer = new NumericTokenizer(),
    temporalTokenizer: TemporalTokenizer = new TemporalTokenizer()
  ) extends BaseTokenizer[Any] {

    override def tokenize(value: Any): Token = value match {
      case null =>
        Token("NULL", TokenType.Null)

      case s: String =>
        stringTokenizer.tokenize(s)

      case bytes: Array[Byte] =>
        stringTokenizer.tokenizeBytes(bytes)

      case n: Number =>
        numericTokenizer.tokenize(n)

      case dt: LocalDateTime =>
        temporalTokenizer.tokenize(dt)

      case d: LocalDate =>
        temporalTokenizer.tokenizeDate(d)

      case t: ToToken[_] =>
        Token(t.asInstanceOf[ToToken[Any]].toToken(value).value, TokenType.Structured)

      case _ =>
        Token(value.toString, TokenType.String, Map("fallback" -> true))
    }
  }

  // ============================================================================
  // Whitespace Tokenizer
  // ============================================================================

  /**
   * Basic tokenizer that splits text by whitespace.
   * Provides options for filtering and normalization.
   */
  class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ) {
    private val punctuation = Set(',', '.', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

    private def processToken(word: String): Option[String] = {
      val processed = if (stripPunctuation) {
        word.filter(c => !punctuation.contains(c))
      } else {
        word
      }.trim

      val result = if (lowercase) {
        processed.toLowerCase
      } else {
        processed
      }

      if (result.length < minLength) None
      else maxLength match {
        case Some(max) if result.length > max => Some(result.take(max))
        case _ if result.nonEmpty => Some(result)
        case _ => None
      }
    }

    /**
     * Split text by whitespace and return list of tokens.
     */
    def tokenize(text: String): List[Token] = {
      val words = text.split("\\s+").toList
      words.zipWithIndex.flatMap { case (word, idx) =>
        processToken(word).map { processed =>
          Token(
            value = processed,
            tokenType = TokenType.String,
            metadata = Map("position" -> idx, "original" -> word)
          )
        }
      }
    }

    /**
     * Split text by whitespace and return list of token strings.
     */
    def tokenizeToStrings(text: String): List[String] =
      tokenize(text).map(_.value)

    /**
     * Tokenize text and return tokens with character positions.
     */
    def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
      val result = scala.collection.mutable.ListBuffer[(String, Int, Int)]()
      var currentPos = 0

      text.split("\\s+").foreach { word =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length

        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }

        currentPos = end
      }

      result.toList
    }

    /**
     * Count the number of tokens in the text.
     */
    def countTokens(text: String): Int =
      tokenize(text).size
  }

  // ============================================================================
  // Tokenizer Builder
  // ============================================================================

  /**
   * Fluent builder for creating custom tokenizers.
   * Type-safe and immutable builder pattern.
   */
  final class TokenizerBuilder[A] private (
    private val normalizers: List[String => String],
    private val validators: List[A => Boolean],
    private val metadata: Map[String, Any]
  ) {
    def this() = this(Nil, Nil, Map.empty)

    /**
     * Add a normalizer function to the builder.
     */
    def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

    /**
     * Add a validator function to the builder.
     */
    def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers, validators :+ validator, metadata)

    /**
     * Add metadata to the builder.
     */
    def withMetadata(additionalMetadata: (String, Any)*): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers, validators, metadata ++ additionalMetadata.toMap)

    /**
     * Build the final tokenizer function.
     */
    def build: A => Token = { value: A =>
      // Validate
      validators.foreach { validator =>
        require(validator(value), s"Validation failed for $value")
      }

      // Convert to string and normalize
      val strValue = normalizers.foldLeft(value.toString) { (acc, normalizer) =>
        normalizer(acc)
      }

      Token(strValue, TokenType.String, metadata)
    }

    /**
     * Build and return a BaseTokenizer.
     */
    def buildTokenizer: BaseTokenizer[A] = new BaseTokenizer[A] {
      override def tokenize(v: A): Token = build(v)
    }
  }

  object TokenizerBuilder {
    def apply[A](): TokenizerBuilder[A] = new TokenizerBuilder[A]()
  }

  // ============================================================================
  // Convenience Functions
  // ============================================================================

  /**
   * Default universal tokenizer instance.
   */
  val defaultUniversalTokenizer: UniversalTokenizer = new UniversalTokenizer()

  /**
   * Tokenize a single value using the universal tokenizer.
   */
  def tokenize(value: Any): Token = defaultUniversalTokenizer.tokenize(value)

  /**
   * Tokenize a batch of values.
   */
  def tokenizeBatch(values: Iterable[Any]): Iterable[Token] =
    new Iterable[Token] {
      override def iterator: Iterator[Token] = values.iterator.map(defaultUniversalTokenizer.tokenize)
    }

  /**
   * Create a ToToken instance for a type.
   */
  def toToken[A](value: A)(implicit ev: ToToken[A]): Token = ev.toToken(value)

  /**
   * Create a token with additional metadata.
   */
  def withMetadata(token: Token, additionalMetadata: (String, Any)*): Token =
    token.withMetadata(additionalMetadata.toMap)

  // ============================================================================
  // Implicits for Type Classes
  // ============================================================================

  object Implicits {
    implicit val stringToToken: ToToken[String] = (value: String) =>
      Token(value, TokenType.String)

    implicit val intToToken: ToToken[Int] = (value: Int) =>
      Token(value.toString, TokenType.Numeric)

    implicit val doubleToToken: ToToken[Double] = (value: Double) =>
      Token(s"%.6f".format(value), TokenType.Numeric)

    implicit val localDateTimeToToken: ToToken[LocalDateTime] = (value: LocalDateTime) =>
      Token(value.toString, TokenType.Temporal)

    implicit val localDateToToken: ToToken[LocalDate] = (value: LocalDate) =>
      Token(value.toString, TokenType.Temporal)

    /**
     * Converter for ToToken instances.
     */
    implicit class ToTokenOps[A](value: A)(implicit ev: ToToken[A]) {
      def toToken: Token = ev.toToken(value)
    }
  }
}

