    case object String extends TokenType
    case object Numeric extends TokenType
    case object Temporal extends TokenType
    case object Structured extends TokenType
    case object Binary extends TokenType
    case object Null extends TokenType

    def fromString(value: String): Option[TokenType] = value.toLowerCase match {
      case "string" => Some(String)
      case "numeric" => Some(Numeric)
      case "temporal" => Some(Temporal)
      case "structured" => Some(Structured)
      case "binary" => Some(Binary)
      case "null" => Some(Null)
      case _ => None
    }
  }

  /**
   * Represents a token with its value, type, and optional metadata.
   * Immutable case class for thread-safety and predictability.
   */
  final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
  ) {
    /**
     * Return a new token with additional metadata merged in.
     */
    def withMetadata(additionalMetadata: (String, Any)*): Token =
      copy(metadata = metadata ++ additionalMetadata.toMap)

    def withMetadata(newMetadata: Map[String, Any]): Token =
      copy(metadata = metadata ++ newMetadata)
  }

  /**
   * Type class for types that can be converted to tokens.
   */
  trait ToToken[A] {
    def toToken(value: A): Token
  }

  /**
   * Type class for normalization of token values.
   */
  trait TokenNormalizer {
    def normalize(value: String): String
  }

  // ============================================================================
  // Tokenizer Base Abstraction
  // ============================================================================

  /**
   * Base trait for all tokenizers.
   * Supports single value tokenization and batch processing via views.
   */
  trait BaseTokenizer[A] {
    def tokenize(value: A): Token

    def tokenizeBatch(values: Iterable[A]): IterableOnce[Token] =
      new IterableOnce[ViewToken](values.iterator.map(tokenize))

    protected class ViewToken(t: Token) extends IterableOnce[Token] {
      def iterator: Iterator[Token] = Iterator(t)
    }
  }

  // ============================================================================
  // Specific Tokenizer Implementations
  // ============================================================================

  /**
   * Tokenizer for string and byte types.
   * Supports configurable encoding and normalization.
   */
  final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: Option[TokenNormalizer] = None
  ) extends BaseTokenizer[String] {

    override def tokenize(value: String): Token = {
      val normalized = normalizer.fold(value)(_.normalize(value))
      Token(normalized, TokenType.String)
    }

    /**
     * Tokenize bytes by first decoding to string.
     */
    def tokenizeBytes(bytes: Array[Byte]): Token = {
      val str = new String(bytes, encoding)
      tokenize(str)
    }
  }

  /**
   * Tokenizer for numeric types.
   * Supports configurable precision for floating point values.
   */
  final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
  ) extends BaseTokenizer[Number] {

    override def tokenize(value: Number): Token = {
      val strValue = value match {
        case d: java.math.BigDecimal =>
          s"%.${precision}f".format(d.doubleValue)
        case d: java.math.BigInteger =>
          d.toString
        case d: Double =>
          s"%.${precision}f".format(d)
        case f: Float =>
          s"%.${precision}f".format(f.toDouble)
        case l: Long =>
          l.toString
        case i: Integer =>
          i.toString
        case _ =>
          value.toString
      }

      Token(strValue, TokenType.Numeric, Map("originalType" -> value.getClass.getSimpleName))
    }
  }

  /**
   * Tokenizer for date/time types.
   * Supports custom format strings and ISO defaults.
   */
  final class TemporalTokenizer(
    formatStr: Option[String] = None
  ) extends BaseTokenizer[LocalDateTime] {

    private val isoFormat = "yyyy-MM-dd'T'HH:mm:ss"
    private val dateFormat = "yyyy-MM-dd"

    override def tokenize(value: LocalDateTime): Token = {
      val fmt = formatStr.getOrElse(isoFormat)
      Token(value.format(java.time.format.DateTimeFormatter.ofPattern(fmt)), TokenType.Temporal)
    }

    /**
     * Tokenize a LocalDate with date-only format.
     */
    def tokenizeDate(value: LocalDate): Token = {
      val fmt = formatStr.getOrElse(dateFormat)
      Token(value.format(java.time.format.DateTimeFormatter.ofPattern(fmt)), TokenType.Temporal)
    }
  }

  // ============================================================================
  // Universal Tokenizer
  // ============================================================================

  /**
   * Universal tokenizer that dispatches to appropriate tokenizer based on type.
   * Demonstrates pattern matching on types.
   */
  class UniversalTokenizer(
    stringTokenizer: StringTokenizer = new StringTokenizer(),
    numericTokenizer: NumericTokenizer = new NumericTokenizer(),
    temporalTokenizer: TemporalTokenizer = new TemporalTokenizer()
  ) extends BaseTokenizer[Any] {

    override def tokenize(value: Any): Token = value match {
      case null =>
        Token("NULL", TokenType.Null)

      case s: String =>
        stringTokenizer.tokenize(s)

      case bytes: Array[Byte] =>
        stringTokenizer.tokenizeBytes(bytes)

      case n: Number =>
        numericTokenizer.tokenize(n)

      case dt: LocalDateTime =>
        temporalTokenizer.tokenize(dt)

      case d: LocalDate =>
        temporalTokenizer.tokenizeDate(d)

      case t: ToToken[_] =>
        Token(t.asInstanceOf[ToToken[Any]].toToken(value).value, TokenType.Structured)

      case _ =>
