    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
  ) {
    /**
     * Return a new token with additional metadata merged in.
     */
    def withMetadata(additionalMetadata: (String, Any)*): Token =
      copy(metadata = metadata ++ additionalMetadata.toMap)

    def withMetadata(newMetadata: Map[String, Any]): Token =
      copy(metadata = metadata ++ newMetadata)
