  // Tokenizer Builder
  // ============================================================================

  /**
   * Fluent builder for creating custom tokenizers.
   * Type-safe and immutable builder pattern.
   */
  final class TokenizerBuilder[A] private (
    private val normalizers: List[String => String],
    private val validators: List[A => Boolean],
    private val metadata: Map[String, Any]
  ) {
    def this() = this(Nil, Nil, Map.empty)

    /**
     * Add a normalizer function to the builder.
     */
    def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

    /**
     * Add a validator function to the builder.
     */
    def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers, validators :+ validator, metadata)

    /**
     * Add metadata to the builder.
     */
    def withMetadata(additionalMetadata: (String, Any)*): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers, validators, metadata ++ additionalMetadata.toMap)

    /**
     * Build the final tokenizer function.
     */
    def build: A => Token = { value: A =>
      // Validate
      validators.foreach { validator =>
        require(validator(value), s"Validation failed for $value")
      }

      // Convert to string and normalize
      val strValue = normalizers.foldLeft(value.toString) { (acc, normalizer) =>
        normalizer(acc)
      }

      Token(strValue, TokenType.String, metadata)
    }

    /**
     * Build and return a BaseTokenizer.
     */
    def buildTokenizer: BaseTokenizer[A] = new BaseTokenizer[A] {
      override def tokenize(v: A): Token = build(v)
    }
  }

  object TokenizerBuilder {
    def apply[A](): TokenizerBuilder[A] = new TokenizerBuilder[A]()
  }

  // ============================================================================
  // Convenience Functions
  // ============================================================================

  /**
   * Default universal tokenizer instance.
   */
  val defaultUniversalTokenizer: UniversalTokenizer = new UniversalTokenizer()

  /**
   * Tokenize a single value using the universal tokenizer.
