  /**
   * Type class for types that can be converted to tokens.
   */
  trait ToToken[A] {
    def toToken(value: A): Token
  }

  /**
   * Type class for normalization of token values.
   */
  trait TokenNormalizer {
    def normalize(value: String): String
  }

  // ============================================================================
  // Tokenizer Base Abstraction
  // ============================================================================

  /**
   * Base trait for all tokenizers.
   * Supports single value tokenization and batch processing via views.
   */
  trait BaseTokenizer[A] {
    def tokenize(value: A): Token

    def tokenizeBatch(values: Iterable[A]): Iterable[Token] =
      new Iterable[Token] {
        override def iterator: Iterator[Token] = values.iterator.map(tokenize)
      }
  }

