  // Specific Tokenizer Implementations
  // ============================================================================

  /**
   * Tokenizer for string and byte types.
   * Supports configurable encoding and normalization.
   */
  final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: Option[TokenNormalizer] = None
  ) extends BaseTokenizer[String] {

    override def tokenize(value: String): Token = {
      val normalized = normalizer.fold(value)(_.normalize(value))
      Token(normalized, TokenType.String)
    }

    /**
     * Tokenize bytes by first decoding to string.
     */
    def tokenizeBytes(bytes: Array[Byte]): Token = {
      val str = new String(bytes, encoding)
      tokenize(str)
    }
  }

  /**
   * Tokenizer for numeric types.
   * Supports configurable precision for floating point values.
   */
  final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
  ) extends BaseTokenizer[Number] {

