   * Tokenizer for date/time types.
   * Supports custom format strings and ISO defaults.
   */
  final class TemporalTokenizer(
    formatStr: Option[String] = None
  ) extends BaseTokenizer[LocalDateTime] {

    private val isoFormat = "yyyy-MM-dd'T'HH:mm:ss"
    private val dateFormat = "yyyy-MM-dd"

    override def tokenize(value: LocalDateTime): Token = {
      val fmt = formatStr.getOrElse(isoFormat)
      Token(value.format(java.time.format.DateTimeFormatter.ofPattern(fmt)), TokenType.Temporal)
