     * Tokenize a LocalDate with date-only format.
     */
    def tokenizeDate(value: LocalDate): Token = {
      val fmt = formatStr.getOrElse(dateFormat)
      Token(value.format(java.time.format.DateTimeFormatter.ofPattern(fmt)), TokenType.Temporal)
    }
  }

  // ============================================================================
  // Universal Tokenizer
  // ============================================================================

  /**
   * Universal tokenizer that dispatches to appropriate tokenizer based on type.
   * Demonstrates pattern matching on types.
   */
  class UniversalTokenizer(
    stringTokenizer: StringTokenizer = new StringTokenizer(),
    numericTokenizer: NumericTokenizer = new NumericTokenizer(),
    temporalTokenizer: TemporalTokenizer = new TemporalTokenizer()
  ) extends BaseTokenizer[Any] {

