      case null =>
        Token("NULL", TokenType.Null)

      case s: String =>
        stringTokenizer.tokenize(s)

      case bytes: Array[Byte] =>
        stringTokenizer.tokenizeBytes(bytes)

      case n: Number =>
        numericTokenizer.tokenize(n)

      case dt: LocalDateTime =>
