      }
    }

    /**
     * Split text by whitespace and return list of token strings.
     */
    def tokenizeToStrings(text: String): List[String] =
      tokenize(text).map(_.value)

    /**
     * Tokenize text and return tokens with character positions.
     */
    def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
      val result = scala.collection.mutable.ListBuffer[(String, Int, Int)]()
      var currentPos = 0

      text.split("\\s+").foreach { word =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length

        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }

        currentPos = end
      }

      result.toList
    }

    /**
     * Count the number of tokens in the text.
     */
    def countTokens(text: String): Int =
      tokenize(text).size
  }

  // ============================================================================
  // Tokenizer Builder
  // ============================================================================

  /**
   * Fluent builder for creating custom tokenizers.
   * Type-safe and immutable builder pattern.
   */
  final class TokenizerBuilder[A] private (
    private val normalizers: List[String => String],
    private val validators: List[A => Boolean],
    private val metadata: Map[String, Any]
  ) {
    def this() = this(Nil, Nil, Map.empty)

    /**
     * Add a normalizer function to the builder.
     */
    def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

    /**
     * Add a validator function to the builder.
     */
    def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers, validators :+ validator, metadata)

    /**
     * Add metadata to the builder.
     */
    def withMetadata(additionalMetadata: (String, Any)*): TokenizerBuilder[A] =
      new TokenizerBuilder(normalizers, validators, metadata ++ additionalMetadata.toMap)

    /**
     * Build the final tokenizer function.
     */
    def build: A => Token = { value: A =>
      // Validate
      validators.foreach { validator =>
        require(validator(value), s"Validation failed for $value")
      }

      // Convert to string and normalize
      val strValue = normalizers.foldLeft(value.toString) { (acc, normalizer) =>
        normalizer(acc)
      }

      Token(strValue, TokenType.String, metadata)
    }

    /**
     * Build and return a BaseTokenizer.
     */
    def buildTokenizer: BaseTokenizer[A] = new BaseTokenizer[A] {
      override def tokenize(v: A): Token = build(v)
    }
  }

  object TokenizerBuilder {
    def apply[A](): TokenizerBuilder[A] = new TokenizerBuilder[A]()
  }

  // ============================================================================
  // Convenience Functions
  // ============================================================================

  /**
   * Default universal tokenizer instance.
   */
  val defaultUniversalTokenizer: UniversalTokenizer = new UniversalTokenizer()

  /**
   * Tokenize a single value using the universal tokenizer.
   */
  def tokenize(value: Any): Token = defaultUniversalTokenizer.tokenize(value)

  /**
   * Tokenize a batch of values.
   */
  def tokenizeBatch(values: Iterable[Any]): Iterable[Token] =
    new Iterable[Token] {
      override def iterator: Iterator[Token] = values.iterator.map(defaultUniversalTokenizer.tokenize)
    }

  /**
   * Create a ToToken instance for a type.
   */
  def toToken[A](value: A)(implicit ev: ToToken[A]): Token = ev.toToken(value)

  /**
   * Create a token with additional metadata.
   */
  def withMetadata(token: Token, additionalMetadata: (String, Any)*): Token =
    token.withMetadata(additionalMetadata.toMap)

  // ============================================================================
  // Implicits for Type Classes
  // ============================================================================

  object Implicits {
    implicit val stringToToken: ToToken[String] = (value: String) =>
      Token(value, TokenType.String)

    implicit val intToToken: ToToken[Int] = (value: Int) =>
      Token(value.toString, TokenType.Numeric)

    implicit val doubleToToken: ToToken[Double] = (value: Double) =>
      Token(s"%.6f".format(value), TokenType.Numeric)

    implicit val localDateTimeToToken: ToToken[LocalDateTime] = (value: LocalDateTime) =>
      Token(value.toString, TokenType.Temporal)

    implicit val localDateToToken: ToToken[LocalDate] = (value: LocalDate) =>
      Token(value.toString, TokenType.Temporal)

    /**
     * Converter for ToToken instances.
     */
    implicit class ToTokenOps[A](value: A)(implicit ev: ToToken[A]) {
      def toToken: Token = ev.toToken(value)
    }
  }
}
